package integration.scenario.webauthn;

import com.webauthn4j.WebAuthnManager;
import com.webauthn4j.converter.AttestationObjectConverter;
import com.webauthn4j.converter.CollectedClientDataConverter;
import com.webauthn4j.converter.util.ObjectConverter;
import com.webauthn4j.credential.CredentialRecord;
import com.webauthn4j.credential.CredentialRecordImpl;
import com.webauthn4j.data.AuthenticationParameters;
import com.webauthn4j.data.AuthenticationRequest;
import com.webauthn4j.data.attestation.AttestationObject;
import com.webauthn4j.data.client.Origin;
import com.webauthn4j.data.client.challenge.DefaultChallenge;
import com.webauthn4j.server.ServerProperty;
import com.webauthn4j.util.HexUtil;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.condition.EnabledForJreRange;
import org.junit.jupiter.api.condition.JRE;

import static org.assertj.core.api.Assertions.assertThatCode;

/**
 * Verifies that ML-DSA WebAuthn authentication works without Bouncy Castle on the classpath.
 * The server-side verification path (public key extraction + signature verification) uses
 * only JDK standard APIs, so BC is not required.
 */
@EnabledForJreRange(min = JRE.JAVA_24)
class MLDSAAuthenticationVerificationTest {

    // --- ML-DSA-65 WebAuthn Fixture ---

    // Registration
    static final byte[] ATTESTATION_OBJECT = HexUtil.decode("");
    static final byte[] REG_CLIENT_DATA_JSON = HexUtil.decode("7B2274797065223A22776562617574686E2E637265617465222C226368616C6C656E6765223A22317948534B62517452647969714E4B5066537A495A41222C226F726967696E223A22687474703A2F2F6578616D706C652E636F6D227D");

    // Authentication
    static final byte[] CREDENTIAL_ID = HexUtil.decode("99F2C8F26A0CCB90D74AE283C1F5670AD93929F5CBA7FADA4F79203410F7C584");
    static final byte[] AUTHENTICATOR_DATA = HexUtil.decode("A379A6F6EEAFB9A55E378C118034E2751E682FAB9F2D30AB13D2125586CE19470500000002");
    static final byte[] AUTH_CLIENT_DATA_JSON = HexUtil.decode("7B2274797065223A22776562617574686E2E676574222C226368616C6C656E6765223A227072305671387361547879624A354D6C324972646B41222C226F726967696E223A22687474703A2F2F6578616D706C652E636F6D227D");
    static final byte[] SIGNATURE = HexUtil.decode("");

    static final byte[] AUTH_CHALLENGE = HexUtil.decode("A6BD15ABCB1A4F1C9B279325D88ADD90");

    @Test
    void authentication_verification_should_succeed_without_bc() {
        ObjectConverter objectConverter = new ObjectConverter();
        AttestationObjectConverter attestationObjectConverter = new AttestationObjectConverter(objectConverter);
        CollectedClientDataConverter collectedClientDataConverter = new CollectedClientDataConverter(objectConverter);
        WebAuthnManager webAuthnManager = WebAuthnManager.createNonStrictWebAuthnManager(objectConverter);

        // Build credential record from registration fixture
        AttestationObject attestationObject = attestationObjectConverter.convert(ATTESTATION_OBJECT);
        var clientData = collectedClientDataConverter.convert(REG_CLIENT_DATA_JSON);
        CredentialRecord credentialRecord = new CredentialRecordImpl(attestationObject, clientData, null, null);

        // Build authentication request from fixture
        AuthenticationRequest authenticationRequest = new AuthenticationRequest(
                CREDENTIAL_ID,
                AUTHENTICATOR_DATA,
                AUTH_CLIENT_DATA_JSON,
                "{}",
                SIGNATURE
        );

        ServerProperty serverProperty = ServerProperty.builder()
                .origin(new Origin("http://example.com"))
                .rpId("example.com")
                .challenge(new DefaultChallenge(AUTH_CHALLENGE))
                .build();

        AuthenticationParameters authenticationParameters = new AuthenticationParameters(
                serverProperty,
                credentialRecord,
                null,
                true
        );

        // Verify - this should work without BC because only getPublicKey() + JCA Signature.verify() are used
        assertThatCode(() -> webAuthnManager.verify(authenticationRequest, authenticationParameters))
                .doesNotThrowAnyException();
    }
}
